{
    "name": "差异菌分析",
    "moduleName": "abundance_difference",
    "script_type": "r",
    "image": "registry.cn-hangzhou.aliyuncs.com/wybioinfo/datascience-notebook:x86_64-ubuntu-22.04",
    "saveAnalysisMethod": "metaphlan_abundance_difference_matrix",
    "dbInputFiled":["control","treatment"],
    "formJson": [
        {
            "name": "group_field",
            "label": "分组列",
            "rules": [
                {
                    "required": true,
                    "message": "该字段不能为空!"
                }
            ],
            "type": "GroupFieldSelect"
        },
        {
            "name": "treatment",
            "label": "处理组",
            "rules": [
                {
                    "required": true,
                    "message": "该字段不能为空!"
                }
            ],
            "type": "GroupSelectSampleButton",
            "group": "group_field",
            "db":true
        },
        {
            "name": "control",
            "label": "对照组",
            "rules": [
                {
                    "required": true,
                    "message": "该字段不能为空!"
                }
            ],
            "type": "GroupSelectSampleButton",
            "group": "group_field",
            "db": true
        },
        {
            "name": "rank",
            "label": "rank",
            "rules": [
                {
                    "required": true,
                    "message": "该字段不能为空!"
                }
            ],
            "type": "RankSelect"
        },{
            "name": "top_num",
            "label": "条形图显示top菌个数:",
            "rules": [
                {
                    "required": true,
                    "message": "该字段不能为空!"
                }
            ],
            "initialValue":20,
            "type": "BaseInputNumber"
        }
    ]
}

{
  "name": "raw_reads",
  "mode": "multiple",
  "type": "GroupSelectSampleButton",
  "label": "Raw Reads",
  "group": "group_field",
  "rules": [
    {
      "required": true,
      "message": "This field cannot be empty!"
    }
  ],
  "dir": "",
  "fileFormat": {
    "profile": "*merge.tsv"
  },
  "inputForm": [
    {
      "name": [
        "content",
        "fastq1"
      ],
      "initialValue": "/data/wangyang/NGS_TEST/*_1.fastq.gz",
      "label": "fastq1",
      "type": "BaseInput",
      "rules": [
        {
          "required": true,
          "message": "This field cannot be empty!"
        }
      ]
    },
    {
      "name": [
        "content",
        "fastq2"
      ],
      "initialValue": "/data/wangyang/NGS_TEST/*_2.fastq.gz",
      "label": "fastq2",
      "type": "BaseInput",
      "rules": [
        {
          "required": true,
          "message": "This field cannot be empty!"
        }
      ]
    }
  ]
}
